import { useState } from 'react';

export default function CourseClicksTable({ clicks }) {
    const isEmpty = !clicks || clicks.length === 0;

    return (
        <div className="table-wrapper">
            <table className="data-table">
                <thead>
                    <tr>
                        <th>User ID</th>
                        <th>User Email</th>
                        <th>Course Title</th>
                        <th>Visited Date</th>
                    </tr>
                </thead>
                <tbody>
                    {isEmpty ? (
                        <tr>
                            <td colSpan="4" style={{ textAlign: 'center', padding: '3rem', color: 'var(--text-secondary)' }}>
                                No course clicks found.
                            </td>
                        </tr>
                    ) : (
                        clicks.map((click) => (
                            <tr key={click.id}>
                                <td style={{ fontFamily: 'monospace', fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                                    {click.user_id !== 'N/A' ? click.user_id.split('-')[0] + '...' : 'N/A'}
                                </td>
                                <td style={{ color: 'var(--accent-primary)', fontSize: '0.85rem' }}>{click.email}</td>
                                <td>
                                    <span style={{ padding: '4px 8px', borderRadius: '4px', fontSize: '0.75rem', fontWeight: 'bold', backgroundColor: 'rgba(59, 130, 246, 0.1)', color: '#3b82f6', textTransform: 'uppercase' }}>
                                        {click.course_title}
                                    </span>
                                </td>
                                <td>
                                    {new Date(click.clicked_at).toLocaleDateString(undefined, {
                                        year: 'numeric',
                                        month: 'short',
                                        day: 'numeric',
                                        hour: '2-digit',
                                        minute: '2-digit'
                                    })}
                                </td>
                            </tr>
                        ))
                    )}
                </tbody>
            </table>
        </div>
    );
}

import { useState } from 'react';

export default function SignInsTable({ signIns }) {
    const isEmpty = !signIns || signIns.length === 0;

    return (
        <div className="table-wrapper">
            <table className="data-table">
                <thead>
                    <tr>
                        <th>User ID</th>
                        <th>User Email-ID</th>
                        <th>Signed In Date</th>
                    </tr>
                </thead>
                <tbody>
                    {isEmpty ? (
                        <tr>
                            <td colSpan="3" style={{ textAlign: 'center', padding: '3rem', color: 'var(--text-secondary)' }}>
                                No sign-ins found.
                            </td>
                        </tr>
                    ) : (
                        signIns.map((s) => (
                            <tr key={s.id}>
                                <td style={{ fontFamily: 'monospace', fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                                    {s.id.split('-')[0]}...
                                </td>
                                <td>
                                    <a href={`mailto:${s.email}`} className="data-table__email">
                                        {s.email}
                                    </a>
                                </td>
                                <td>
                                    {new Date(s.last_sign_in_at).toLocaleDateString('en-US', {
                                        weekday: 'short',
                                        year: 'numeric',
                                        month: 'short',
                                        day: 'numeric',
                                        hour: '2-digit',
                                        minute: '2-digit'
                                    })}
                                </td>
                            </tr>
                        ))
                    )}
                </tbody>
            </table>
        </div>
    );
}

import { createContext, useContext, useState, useEffect } from 'react';
import { apiRequest } from '../config/api';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
    const [user, setUser] = useState(null);
    const [profile, setProfile] = useState(null);
    const [loading, setLoading] = useState(true);

    // Check for existing session on mount
    useEffect(() => {
        const token = localStorage.getItem('access_token');
        if (token) {
            fetchUser();
        } else {
            setLoading(false);
        }
    }, []);

    async function fetchUser() {
        try {
            const data = await apiRequest('/auth/me');
            setUser(data.user);
            setProfile(data.profile);
        } catch (err) {
            console.error('Failed to fetch user:', err);
            localStorage.removeItem('access_token');
            setUser(null);
            setProfile(null);
        } finally {
            setLoading(false);
        }
    }

    async function signIn(email, password) {
        const data = await apiRequest('/auth/sign-in', {
            method: 'POST',
            body: JSON.stringify({ email, password }),
        });

        localStorage.setItem('access_token', data.session.access_token);
        setUser(data.user);
        await fetchUser(); // get profile data
        return data;
    }

    async function signUp(email, password, full_name) {
        const data = await apiRequest('/auth/sign-up', {
            method: 'POST',
            body: JSON.stringify({ email, password, full_name }),
        });

        localStorage.setItem('access_token', data.session.access_token);
        setUser(data.user);
        await fetchUser();
        return data;
    }

    function signOut() {
        localStorage.removeItem('access_token');
        setUser(null);
        setProfile(null);
    }

    const value = {
        user,
        profile,
        loading,
        signIn,
        signUp,
        signOut,
        isAuthenticated: !!user,
    };

    return (
        <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (!context) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
}

import { useState, useEffect } from 'react';
import { apiRequest } from '../config/api';
import CourseClicksTable from '../components/Course/CourseClicksTable';
import { HiOutlineCursorClick } from 'react-icons/hi';
import toast from 'react-hot-toast';

export default function CourseClicks() {
    const [clicks, setClicks] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchClicks();
    }, []);

    const fetchClicks = async () => {
        try {
            setLoading(true);
            const { data } = await api.get('/course-clicks-details');
            setClicks(data.clicks || []);
        } catch (error) {
            console.error('Error fetching course clicks:', error);
            toast.error('Failed to load course clicks');
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="page-loading">
                <div className="spinner"></div>
                <p>Loading course interactions...</p>
            </div>
        );
    }

    return (
        <div className="page">
            <header className="page__header">
                <div>
                    <h1 className="page__title">Course Interactions</h1>
                    <p className="page__subtitle">View details of users who have engaged with course materials.</p>
                </div>
                <div style={{
                    width: '48px', height: '48px', borderRadius: '12px',
                    background: 'rgba(59, 130, 246, 0.1)', display: 'flex',
                    alignItems: 'center', justifyContent: 'center', color: '#3b82f6',
                    fontSize: '1.5rem'
                }}>
                    <HiOutlineCursorClick />
                </div>
            </header>

            <div className="card">
                <CourseClicksTable clicks={clicks} />
            </div>
        </div>
    );
}
